import{_ as e,c as s,o as i,b0 as l}from"./chunks/framework.Becqh7-x.js";const t="/linux-dev-docs/assets/image-20241102154223658.DRy6RSmA.png",n="/linux-dev-docs/assets/image-20241102154828885.bdQOaqUm.png",r="/linux-dev-docs/assets/image-20241102154942593.B-nBkmOR.png",o="/linux-dev-docs/assets/image-20241111220726643.Cw4eL5no.png",h="/linux-dev-docs/assets/image-20241111234927427.BcsYmRLE.png",p="/linux-dev-docs/assets/image-20260108113237554.Dx6iRzQS.png",d="/linux-dev-docs/assets/image-20241111235258585.4BIebjPH.png",f=JSON.parse('{"title":"LV055-201904版本移植","description":null,"frontmatter":{"title":"LV055-201904版本移植","date":"2026-01-08T11:19:43.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/img/uboot/126d2c8c10472b4febd5a4ba","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-08T11:19:43.692Z","fulluuid":"febd5a4ba3b54c42b5cda1a7ae9a3e46","useduuid":"febd5a4ba"}},"headers":[],"relativePath":"sdoc/img/uboot/126d2c8c10472b4febd5a4ba.md","filePath":"sdoc/15-系统镜像/10-uboot/LV055-201904版本移植.md","lastUpdated":1768604092000}'),c={name:"sdoc/img/uboot/126d2c8c10472b4febd5a4ba.md"};function u(m,a,b,k,g,_){return i(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="lv055-201904版本移植" tabindex="-1">LV055-201904版本移植 <a class="header-anchor" href="#lv055-201904版本移植" aria-label="Permalink to &quot;LV055-201904版本移植&quot;">​</a></h1><p>这一篇笔记，我们来将这个 2019.04 版本的 uboot 移植到自己的开发板。源码可以在这里下载：<a href="https://github.com/nxp-imx/uboot-imx/releases/tag/rel_imx_4.19.35_1.1.0" target="_blank" rel="noreferrer">Release rel_imx_4.19.35_1.1.0: MLK-22866 imx8: Remove the optee shared memory from DDR banks · nxp-imx/uboot-imx · GitHub</a></p><h2 id="一、开发板默认配置文件" tabindex="-1">一、开发板默认配置文件 <a class="header-anchor" href="#一、开发板默认配置文件" aria-label="Permalink to &quot;一、开发板默认配置文件&quot;">​</a></h2><h3 id="_1-添加默认配置文件" tabindex="-1">1. 添加默认配置文件 <a class="header-anchor" href="#_1-添加默认配置文件" aria-label="Permalink to &quot;1. 添加默认配置文件&quot;">​</a></h3><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configs/mx6ull_14x14_evk_emmc_defconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configs/mx6ull_alpha_emmc_defconfig</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-修改配置文件" tabindex="-1">2. 修改配置文件 <a class="header-anchor" href="#_2-修改配置文件" aria-label="Permalink to &quot;2. 修改配置文件&quot;">​</a></h3><p>然后将文件 <code>mx6ull_alpha_defconfig</code> 中的内容改成下面的：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_TARGET_MX6ULL_14X14_EVK=y --&gt; CONFIG_TARGET_MX6ULL_ALPHA_EMMC=y</span></span>
<span class="line"><span>CONFIG_DEFAULT_DEVICE_TREE=&quot;imx6ull-14x14-evk&quot; --&gt; CONFIG_DEFAULT_DEVICE_TREE=&quot;imx6ull-alpha-emmc&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>CONFIG_DEFAULT_DEVICE_TREE</code> 配置项所配置的是 uboot 启动时所需要的设备树名。</p><h2 id="二、开发板对应的头文件" tabindex="-1">二、开发板对应的头文件 <a class="header-anchor" href="#二、开发板对应的头文件" aria-label="Permalink to &quot;二、开发板对应的头文件&quot;">​</a></h2><h3 id="_1-添加开发板默认头文件" tabindex="-1">1. 添加开发板默认头文件 <a class="header-anchor" href="#_1-添加开发板默认头文件" aria-label="Permalink to &quot;1. 添加开发板默认头文件&quot;">​</a></h3><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> include/configs/mx6ullevk.h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> include/configs/mx6ull_alpha_emmc.h</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-修改头文件" tabindex="-1">2. 修改头文件 <a class="header-anchor" href="#_2-修改头文件" aria-label="Permalink to &quot;2. 修改头文件&quot;">​</a></h3><p><a href="https://gitee.com/linux-dev-org/imx6ull-uboot/commit/5862a61bb0759b2b3fc5b319aead80c934192bd6" target="_blank" rel="noreferrer">[alpha emmc] 修改头文件 · 5862a61 · linux-dev-org/imx6ull-uboot</a></p><h2 id="三、开发板对应的板级文件" tabindex="-1">三、开发板对应的板级文件 <a class="header-anchor" href="#三、开发板对应的板级文件" aria-label="Permalink to &quot;三、开发板对应的板级文件&quot;">​</a></h2><h3 id="_1-添加开发板对应的板级文件" tabindex="-1">1. 添加开发板对应的板级文件 <a class="header-anchor" href="#_1-添加开发板对应的板级文件" aria-label="Permalink to &quot;1. 添加开发板对应的板级文件&quot;">​</a></h3><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> board/freescale/mx6ullevk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  board/freescale/mx6ull_alpha_emmc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-修改板级文件" tabindex="-1">2. 修改板级文件 <a class="header-anchor" href="#_2-修改板级文件" aria-label="Permalink to &quot;2. 修改板级文件&quot;">​</a></h3><p>这里要改 c 文件，Makefile，MAINTAINERS，Kconfig，imximage.cfg 共计五项内容。</p><p><a href="https://gitee.com/linux-dev-org/imx6ull-uboot/commit/17486c66e63daad15abf077d9b3ae9d424e694ae" target="_blank" rel="noreferrer">[alpha emmc] 修改板级文件夹相关文件 · 17486c6 · linux-dev-org/imx6ull-uboot</a></p><h2 id="四、设备树文件" tabindex="-1">四、设备树文件 <a class="header-anchor" href="#四、设备树文件" aria-label="Permalink to &quot;四、设备树文件&quot;">​</a></h2><p>这里不添加的话，会报错。</p><h3 id="_1-添加设备树文件" tabindex="-1">1. 添加设备树文件 <a class="header-anchor" href="#_1-添加设备树文件" aria-label="Permalink to &quot;1. 添加设备树文件&quot;">​</a></h3><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arch/arm/dts/imx6ull-14x14-evk.dts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arch/arm/dts/imx6ull-alpha-emmc.dts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-修改设备树-makefile" tabindex="-1">2. 修改设备树 Makefile <a class="header-anchor" href="#_2-修改设备树-makefile" aria-label="Permalink to &quot;2. 修改设备树 Makefile&quot;">​</a></h3><p><a href="https://gitee.com/linux-dev-org/imx6ull-uboot/commit/982d6102adf561f0839b69e85788b294159964c4" target="_blank" rel="noreferrer">[alpha emmc] 修改设备树 Makefile · 982d610 · linux-dev-org/imx6ull-uboot</a></p><h2 id="五、网口移植" tabindex="-1">五、网口移植 <a class="header-anchor" href="#五、网口移植" aria-label="Permalink to &quot;五、网口移植&quot;">​</a></h2><h3 id="_1-相关文件修改" tabindex="-1">1. 相关文件修改 <a class="header-anchor" href="#_1-相关文件修改" aria-label="Permalink to &quot;1. 相关文件修改&quot;">​</a></h3><p>直接看这里吧：<a href="https://gitee.com/linux-dev-org/imx6ull-uboot/commit/f67570a2e30b5998ee2496f7eaea5641f32de636" target="_blank" rel="noreferrer">[alpha emmc] 移植网口驱动(使用板子上的 ETH2) · f67570a · linux-dev-org/imx6ull-uboot</a></p><h3 id="_2-开发板验证" tabindex="-1">2. 开发板验证 <a class="header-anchor" href="#_2-开发板验证" aria-label="Permalink to &quot;2. 开发板验证&quot;">​</a></h3><p>我们编译完烧写到 SD 卡，并设置开发板从 SD 卡启动：</p><img src="`+t+`" alt="image-20241102154223658"><p>会发现还是一堆报错，这是因为我们没有配置相关的 IP：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ubuntu  192.168.10.101</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># windows 192.168.10.100</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth1addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 32:34:46:78:9A:DD</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 本地 MAC 地址</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serverip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.101</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 服务器端地址</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ipaddr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.102</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 本机地址</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">saveenv</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>然后再重启，就不会有那些了：</p><img src="`+n+'" alt="image-20241102154828885"><p>我们来 ping 一下 ubuntu 和 windows：</p><img src="'+r+'" alt="image-20241102154942593"><p>发现都是没啥问题的。</p><h2 id="六、lcd-移植" tabindex="-1">六、LCD 移植 <a class="header-anchor" href="#六、lcd-移植" aria-label="Permalink to &quot;六、LCD 移植&quot;">​</a></h2><p>LCD 原本就能用，只是显示不正常，这里先不管。</p><h2 id="七、emmc-移植" tabindex="-1">七、eMMC 移植 <a class="header-anchor" href="#七、emmc-移植" aria-label="Permalink to &quot;七、eMMC 移植&quot;">​</a></h2><h3 id="_1-问题的出现" tabindex="-1">1. 问题的出现 <a class="header-anchor" href="#_1-问题的出现" aria-label="Permalink to &quot;1. 问题的出现&quot;">​</a></h3><p>这里原本以为不用管，因为在移植 uboot 2016 版本的时候是没有 eMMC 的问题的，但是后面在回顾 uboot 的命令的时候发现 eMMc 竟然无法使用：</p><img src="'+o+'" alt="image-20241111220726643"><h3 id="_2-问题原因" tabindex="-1">2. 问题原因 <a class="header-anchor" href="#_2-问题原因" aria-label="Permalink to &quot;2. 问题原因&quot;">​</a></h3><p>emmc 的复位脚，在设备树上没有配置，需要添加。emmc 的复位引脚是这个：</p><img src="'+h+'" alt="image-20241111234927427"><h3 id="_3-设备树修改" tabindex="-1">3. 设备树修改 <a class="header-anchor" href="#_3-设备树修改" aria-label="Permalink to &quot;3. 设备树修改&quot;">​</a></h3><p>可以看这里：<a href="https://gitee.com/linux-dev-org/imx6ull-uboot/commit/afdbdfb9eed76330bc8c6dcfeba8945942053171" target="_blank" rel="noreferrer">[alpha emmc] 设备树添加 alpha 开发板 eMMC 信息 · afdbdfb · linux-dev-org/imx6ull-uboot</a></p><p><img src="'+p+'" alt="image-20260108113237554"></p><h3 id="_4-开发板验证" tabindex="-1">4. 开发板验证 <a class="header-anchor" href="#_4-开发板验证" aria-label="Permalink to &quot;4. 开发板验证&quot;">​</a></h3><p>然后我们烧写到 SD 卡中，启动一下：</p><img src="'+d+'" alt="image-20241111235258585"><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/u013171226/article/details/134556944" target="_blank" rel="noreferrer">移植 NXP 官方 uboot 到 IMX6ULL 开发板--以及过程中遇到的疑问和错误记录_nxp imx6ulz secure boot-CSDN 博客</a></p><p><a href="https://www.bilibili.com/opus/664794988236767233" target="_blank" rel="noreferrer">移植新的uboot到正点原子imx6ull开发板遇到emmc的问题 - 哔哩哔哩 (bilibili.com)</a></p></blockquote>',55)])])}const v=e(c,[["render",u]]);export{f as __pageData,v as default};
